#include <vector>
#include <string>
#include <cstddef>
#include <omp.h>

struct Book {
    std::string title;
    int pages;
};

size_t findLastShortBook(std::vector<Book> const& books) {
    const size_t n = books.size();
    size_t last = n; // sentinel meaning "not found"

    #pragma omp parallel
    {
        size_t local_last = n;

        #pragma omp for nowait
        for (size_t i = 0; i < n; ++i) {
            if (books[i].pages < 100) {
                if (local_last == n || i > local_last) {
                    local_last = i;
                }
            }
        }

        #pragma omp critical
        {
            if (local_last != n && (last == n || local_last > last)) {
                last = local_last;
            }
        }
    }

    return last;
}
